const onSuccess = calItem =>
  listener(calItem.calendar, Cr.NS_OK, Ci.calIOperationListener.ADD, calItem.id, calItem);
const onError = e =>
  listener(
    item.calendar,
    e.result || Cr.NS_ERROR_FAILURE,
    Ci.calIOperationListener.ADD,
    item.id,
    e
  );

doModifyItem(newItem, oldItem, listener) {
  const onSuccess = item =>
    listener(item.calendar, Cr.NS_OK, Ci.calIOperationListener.MODIFY, item.id, item);
  const onError = e =>
    listener(
      oldItem.calendar,
      e.result || Cr.NS_ERROR_FAILURE,
      Ci.calIOperationListener.MODIFY,
      oldItem.id,
      e
    );
